<?php
namespace App\Services;
use DateTimeImmutable;
use DateTimeZone;
use DomainException;
use Throwable;
final class ReportService {
 public function __construct(private int $shop){}
 public static function filters(array $input):array {
  $today=new DateTimeImmutable('today',new DateTimeZone('Asia/Kolkata'));$preset=$input['period']??(isset($input['from'])||isset($input['to'])?'custom':'month');
  [$from,$to]=match($preset){'today'=>[$today,$today],'yesterday'=>[$today->modify('-1 day'),$today->modify('-1 day')],'week'=>[$today->modify('monday this week'),$today],'month'=>[$today->modify('first day of this month'),$today],'last_month'=>[$today->modify('first day of last month'),$today->modify('last day of last month')],'custom'=>[null,null],default=>throw new DomainException('Choose a valid report period.')};
  $dates=$preset==='custom'?RevenueReportService::dates(['from'=>$input['from']??'','to'=>$input['to']??'']):['from'=>$from->format('Y-m-d'),'to'=>$to->format('Y-m-d')];
  $days=(new DateTimeImmutable($dates['from']))->diff(new DateTimeImmutable($dates['to']))->days;
  $group=$input['group']??($days>180?'month':($days>45?'week':'day'));if(!in_array($group,['day','week','month'],true))throw new DomainException('Choose day, week or month grouping.');
  $status=$input['status']??'active';if(!in_array($status,['active','inactive','archived','all'],true))throw new DomainException('Choose a valid inventory status.');
  $stock=$input['stock']??'';if(!in_array($stock,['','low','out','in','untracked','no_sales'],true))throw new DomainException('Choose a valid stock filter.');
  return $dates+['period'=>$preset,'group'=>$group,'q'=>mb_substr(trim(is_string($input['q']??null)?$input['q']:''),0,150),'category_id'=>ProductService::optionalId($input['category_id']??''),'status'=>$status,'stock'=>$stock,'page'=>max(1,(int)($input['page']??1)),'sort'=>is_string($input['sort']??null)?$input['sort']:'','direction'=>($input['direction']??'desc')==='asc'?'asc':'desc'];
 }
 private function period(array $f,string $column='s.created_at'):array {return ["$column>=? AND $column<?",[$f['from'].' 00:00:00',(new DateTimeImmutable($f['to']))->modify('+1 day')->format('Y-m-d').' 00:00:00']];}
 private function eligible(array $f):array {[$date,$args]=$this->period($f);return ["s.shop_id=? AND $date AND NOT EXISTS(SELECT 1 FROM sale_cancellations cancelled WHERE cancelled.shop_id=s.shop_id AND cancelled.sale_id=s.id)",[$this->shop,...$args]];}
 private function query(string $sql,array $args=[]):\PDOStatement {$q=db()->prepare($sql);$q->execute($args);return $q;}
 private static function amount(string $snapshot,string $field):string {return "CASE WHEN JSON_VALID($snapshot) AND JSON_UNQUOTE(JSON_EXTRACT($snapshot,'$.$field')) REGEXP '^[0-9]+([.][0-9]{1,2})?$' THEN CAST(JSON_UNQUOTE(JSON_EXTRACT($snapshot,'$.$field')) AS DECIMAL(15,2)) ELSE NULL END";}
 private function costKnown():string {
  // The invoice cost must agree with its original inventory movement, never today's balance.
  // A recorded zero is accepted only with an explicit zero-cost receipt since last depletion.
  return "(m.id IS NOT NULL AND m.movement_type='sale' AND m.reference_type='sale' AND BINARY m.reference_id=BINARY CAST(i.sale_id AS CHAR) AND m.quantity_delta=-i.quantity AND m.unit_cost=i.unit_cost AND m.previous_quantity IS NOT NULL AND m.resulting_quantity IS NOT NULL AND m.previous_average_cost=i.unit_cost AND (i.unit_cost>0 OR EXISTS(SELECT 1 FROM stock_movements z WHERE z.shop_id=i.shop_id AND z.product_id=i.product_id AND z.id<m.id AND z.quantity_delta>0 AND z.cost_provided=1 AND z.unit_cost=0 AND z.resulting_average_cost=0 AND NOT EXISTS(SELECT 1 FROM stock_movements empty_stock WHERE empty_stock.shop_id=z.shop_id AND empty_stock.product_id=z.product_id AND empty_stock.id>z.id AND empty_stock.id<m.id AND empty_stock.resulting_quantity=0))))";
 }
 private function invoiceReconciled():string {return "s.taxable=(COALESCE((SELECT SUM(".self::amount('li.snapshot','taxable').") FROM sale_items li WHERE li.shop_id=s.shop_id AND li.sale_id=s.id),0)+COALESCE((SELECT SUM(ls.revenue) FROM sale_services ls WHERE ls.shop_id=s.shop_id AND ls.sale_id=s.id),0))";}
 private function lines(array $f):array {[$where,$args]=$this->eligible($f);$net=self::amount('i.snapshot','taxable');$known=$this->costKnown();$reconciled=$this->invoiceReconciled();return ["SELECT i.*,s.invoice_number,s.created_at,p.name,p.sku,p.category_id,p.brand_id,$net AS revenue,CASE WHEN $known THEN 1 ELSE 0 END cost_known,CASE WHEN $reconciled THEN 1 ELSE 0 END invoice_known FROM sale_items i JOIN sales s ON s.shop_id=i.shop_id AND s.id=i.sale_id JOIN products p ON p.shop_id=i.shop_id AND p.id=i.product_id LEFT JOIN stock_movements m ON m.shop_id=i.shop_id AND m.product_id=i.product_id AND m.id=i.movement_id WHERE $where",$args];}
 public function consistent(callable $fn):mixed {$pdo=db();$own=!$pdo->inTransaction();if($own)$pdo->beginTransaction();try{$result=$fn();if($own)$pdo->commit();return $result;}catch(Throwable $e){if($own && $pdo->inTransaction())$pdo->rollBack();throw $e;}}
 public function summary(array $f):array {
  [$where,$args]=$this->eligible($f);$s=$this->query("SELECT COUNT(*) invoice_count,COALESCE(SUM(s.total),0) total_sales,COALESCE(SUM(s.taxable),0) revenue,COALESCE(SUM(s.discount),0) discounts,COALESCE(SUM(s.balance_due),0) credit FROM sales s WHERE $where",$args)->fetch();
  $service=(string)$this->query("SELECT COALESCE(SUM(l.revenue),0) FROM sale_services l JOIN sales s ON s.shop_id=l.shop_id AND s.id=l.sale_id WHERE $where",$args)->fetchColumn();
  [$lines,$la]=$this->lines($f);$cost=$this->query("SELECT COALESCE(SUM(CASE WHEN cost_known=1 THEN quantity*unit_cost ELSE 0 END),0) known_cogs,COALESCE(SUM(cost_known=0 OR revenue IS NULL),0) unknown_cost_lines,COALESCE(SUM(revenue),0) line_revenue FROM ($lines) report_lines",$la)->fetch();
  $product=bcsub($s['revenue'],$service,2);$unreconciled=$this->query("SELECT COUNT(*) FROM sales s WHERE $where AND NOT (".$this->invoiceReconciled().")",$args)->fetchColumn();
  $unknown=(int)$cost['unknown_cost_lines'];$cogs=$unknown || $unreconciled?null:SaleTaxService::round($cost['known_cogs']);
  [$pd,$pa]=$this->period($f,'p.payment_date');$refund=(string)$this->query("SELECT COALESCE(-SUM(p.amount),0) FROM sale_payments p WHERE p.shop_id=? AND $pd AND p.reverses_payment_id IS NOT NULL",[$this->shop,...$pa])->fetchColumn();
  [$sd,$sa]=$this->period($f);$cancelled=(int)$this->query("SELECT COUNT(*) FROM sales s JOIN sale_cancellations c ON c.shop_id=s.shop_id AND c.sale_id=s.id WHERE s.shop_id=? AND $sd",[$this->shop,...$sa])->fetchColumn();
  return $s+['product_revenue'=>$unreconciled?null:$product,'service_revenue'=>$unreconciled?null:$service,'service_gross_profit'=>$unreconciled?null:$service,'known_cogs'=>SaleTaxService::round($cost['known_cogs']),'product_cogs'=>$cogs,'product_gross_profit'=>$cogs===null?null:bcsub($product,$cogs,2),'gross_profit'=>$cogs===null?null:bcsub($s['revenue'],$cogs,2),'average_invoice'=>(int)$s['invoice_count']?SaleTaxService::round(bcdiv($s['total_sales'],(string)$s['invoice_count'],8)):'0.00','unknown_cost_lines'=>$unknown,'unreconciled_invoices'=>(int)$unreconciled,'refunds'=>$refund,'cancelled_invoices'=>$cancelled];
 }
 public function inventorySummary():array {$stats=(new InventoryService($this->shop))->overview();$s=$this->query('SELECT COALESCE(SUM(quantity*average_unit_cost),0) valuation FROM stock_balances WHERE shop_id=?',[$this->shop])->fetch();$mismatches=(int)$this->query('SELECT COUNT(*) FROM products p LEFT JOIN stock_balances b ON b.shop_id=p.shop_id AND b.product_id=p.id LEFT JOIN (SELECT product_id,SUM(quantity_delta) quantity FROM stock_movements WHERE shop_id=? GROUP BY product_id) ledger ON ledger.product_id=p.id WHERE p.shop_id=? AND COALESCE(b.quantity,0)<>COALESCE(ledger.quantity,0)',[$this->shop,$this->shop])->fetchColumn();return $stats+['valuation'=>SaleTaxService::round($s['valuation']),'ledger_mismatches'=>$mismatches];}
 public function categories():array {return $this->query('SELECT id,name FROM categories WHERE shop_id=? ORDER BY name',[$this->shop])->fetchAll();}
 public function trend(array $f):array {
  [$where,$args]=$this->eligible($f);$period=match($f['group']){'week'=>'DATE_SUB(DATE(s.created_at),INTERVAL WEEKDAY(s.created_at) DAY)','month'=>"DATE_FORMAT(s.created_at,'%Y-%m-01')",default=>'DATE(s.created_at)'};
  return $this->query("SELECT $period period,COUNT(*) invoices,SUM(s.total) sales,SUM(s.taxable) revenue FROM sales s WHERE $where GROUP BY period ORDER BY period",$args)->fetchAll();
 }
 public function payments(array $f):array {
  [$where,$args]=$this->period($f,'p.payment_date');$rows=$this->query("SELECT p.method,COALESCE(SUM(CASE WHEN p.reverses_payment_id IS NULL THEN p.amount ELSE 0 END),0) received,COALESCE(-SUM(CASE WHEN p.reverses_payment_id IS NOT NULL THEN p.amount ELSE 0 END),0) refunded,COALESCE(SUM(p.amount),0) net FROM sale_payments p WHERE p.shop_id=? AND $where GROUP BY p.method",[$this->shop,...$args])->fetchAll();$map=array_column($rows,null,'method');$result=[];foreach(['cash'=>'Cash','upi'=>'UPI','card'=>'Card','bank'=>'Bank Transfer'] as $method=>$label)$result[]=['method'=>$method,'label'=>$label]+($map[$method]??['received'=>'0.00','refunded'=>'0.00','net'=>'0.00']);
  [$eligible,$ea]=$this->eligible($f);$credit=(string)$this->query("SELECT COALESCE(SUM(s.balance_due),0) FROM sales s WHERE $eligible",$ea)->fetchColumn();$result[]=['method'=>'credit','label'=>'Credit (unpaid)','received'=>$credit,'refunded'=>null,'net'=>null];return $result;
 }
 private function productConditions(array $f,string $alias='p'):array {$w=[];$a=[];if($f['q']!==''){$w[]="($alias.name LIKE ? OR $alias.sku LIKE ? OR $alias.part_number LIKE ? OR b.name LIKE ?)";array_push($a,...array_fill(0,4,'%'.$f['q'].'%'));}if($f['category_id']){$w[]="$alias.category_id=?";$a[]=$f['category_id'];}return [$w,$a];}
 public function dataset(string $kind,array $f):array {
  [$eligible,$args]=$this->eligible($f);
  if($kind==='products'){
   [$lines,$args]=$this->lines($f);$w=[];$a=[];if($f['q']!==''){$w[]='(l.name LIKE ? OR l.sku LIKE ? OR b.name LIKE ?)';array_push($a,...array_fill(0,3,'%'.$f['q'].'%'));}if($f['category_id']){$w[]='l.category_id=?';$a[]=$f['category_id'];}$where=$w?' WHERE '.implode(' AND ',$w):'';
   $sql="SELECT l.product_id,l.name,l.sku,SUM(l.quantity) quantity,CASE WHEN COUNT(l.revenue)=COUNT(*) THEN SUM(l.revenue) ELSE NULL END revenue,CASE WHEN SUM(l.cost_known=0 OR l.invoice_known=0)=0 THEN ROUND(SUM(l.quantity*l.unit_cost),2) ELSE NULL END cogs,SUM(l.cost_known=0 OR l.revenue IS NULL OR l.invoice_known=0) missing_cost_lines FROM ($lines) l LEFT JOIN brands b ON b.shop_id=l.shop_id AND b.id=l.brand_id $where GROUP BY l.product_id,l.name,l.sku";
   return ["SELECT p.*,CASE WHEN p.missing_cost_lines=0 THEN p.revenue-p.cogs ELSE NULL END profit,CASE WHEN p.missing_cost_lines=0 AND p.revenue<>0 THEN ROUND((p.revenue-p.cogs)/p.revenue*100,2) ELSE NULL END margin FROM ($sql) p",[...$args,...$a]];
  }
  if($kind==='exceptions'){[$lines,$args]=$this->lines($f);return ["SELECT l.id,l.sale_id,l.invoice_number,l.name,l.sku,l.quantity,l.unit_cost,l.movement_id,CASE WHEN l.invoice_known=0 THEN 'Invoice does not reconcile to recorded line revenue' WHEN l.revenue IS NULL THEN 'Missing or invalid revenue snapshot' WHEN l.unit_cost=0 THEN 'Zero cost without verified receipt basis' ELSE 'Missing or inconsistent original movement/cost snapshot' END reason FROM ($lines) l WHERE l.cost_known=0 OR l.revenue IS NULL OR l.invoice_known=0",$args];}
  if($kind==='stock'){
   [$where,$pa]=$this->productConditions($f);array_unshift($where,'p.shop_id=?');$pa=[$this->shop,...$pa];if($f['status']==='archived')$where[]='p.archived_at IS NOT NULL';elseif($f['status']!=='all'){$where[]='p.archived_at IS NULL AND p.status=?';$pa[]=$f['status'];}
   $stock=$f['stock'];if($stock==='low')$where[]='sb.quantity>0 AND p.reorder_level>0 AND sb.quantity<=p.reorder_level';elseif($stock==='out')$where[]='sb.quantity=0';elseif($stock==='in')$where[]='sb.quantity>p.reorder_level';elseif($stock==='untracked')$where[]='sb.product_id IS NULL';elseif($stock==='no_sales')$where[]='COALESCE(sold.quantity,0)=0';
   $sql="SELECT p.id product_id,p.name,p.sku,c.name category,b.name brand,p.status,p.archived_at,sb.quantity,sb.average_unit_cost,p.reorder_level,ROUND(sb.quantity*sb.average_unit_cost,2) stock_value,COALESCE(sold.quantity,0) sold_quantity,sold.last_sale,CASE WHEN sb.product_id IS NULL THEN 'Not tracked' WHEN sb.quantity=0 THEN 'Out of stock' WHEN sb.quantity<=p.reorder_level AND p.reorder_level>0 THEN 'Low stock' ELSE 'In stock' END stock_status FROM products p JOIN categories c ON c.shop_id=p.shop_id AND c.id=p.category_id LEFT JOIN brands b ON b.shop_id=p.shop_id AND b.id=p.brand_id LEFT JOIN stock_balances sb ON sb.shop_id=p.shop_id AND sb.product_id=p.id LEFT JOIN (SELECT i.product_id,SUM(i.quantity) quantity,MAX(s.created_at) last_sale FROM sale_items i JOIN sales s ON s.shop_id=i.shop_id AND s.id=i.sale_id WHERE $eligible GROUP BY i.product_id) sold ON sold.product_id=p.id WHERE ".implode(' AND ',$where);return [$sql,[...$args,...$pa]];
  }
  if($kind==='invoice_exceptions'){[$sql,$args]=$this->dataset('invoices',$f);return ["SELECT * FROM ($sql) invoice_issues WHERE reconciled=0 AND status='Posted'",$args];}
  if($kind==='invoices'){
   $reconciled=$this->invoiceReconciled();
   [$date,$da]=$this->period($f);$q='';$qa=[];if($f['q']!==''){$q=" AND (s.invoice_number LIKE ? OR JSON_UNQUOTE(JSON_EXTRACT(s.customer_snapshot,'$.name')) LIKE ? OR JSON_UNQUOTE(JSON_EXTRACT(s.customer_snapshot,'$.phone')) LIKE ?)";$qa=array_fill(0,3,'%'.$f['q'].'%');}
   return ["SELECT s.id,CASE WHEN $reconciled THEN 1 ELSE 0 END reconciled,s.invoice_number,s.created_at,JSON_UNQUOTE(JSON_EXTRACT(s.customer_snapshot,'$.name')) customer,s.total,s.taxable,s.discount,s.amount_paid,s.balance_due,IF(c.id IS NULL,'Posted','Cancelled (excluded)') status FROM sales s LEFT JOIN sale_cancellations c ON c.shop_id=s.shop_id AND c.sale_id=s.id WHERE s.shop_id=? AND $date $q",[$this->shop,...$da,...$qa]];
  }
  if($kind==='services'){return ["SELECT l.id,s.invoice_number,s.created_at,l.description,l.revenue,".self::amount('l.snapshot','total')." total FROM sale_services l JOIN sales s ON s.shop_id=l.shop_id AND s.id=l.sale_id WHERE $eligible",$args];}
  if($kind==='payments'){[$date,$da]=$this->period($f,'p.payment_date');return ["SELECT p.id,s.invoice_number,p.payment_date,p.method,p.amount,p.received,p.change_returned,p.reference,p.reverses_payment_id FROM sale_payments p JOIN sales s ON s.shop_id=p.shop_id AND s.id=p.sale_id WHERE p.shop_id=? AND $date",[$this->shop,...$da]];}
  if($kind==='movements'){
   $where=['m.shop_id=?','COALESCE(m.entry_date,DATE(m.created_at)) BETWEEN ? AND ?'];$ma=[$this->shop,$f['from'],$f['to']];if($f['q']!==''){$where[]='(p.name LIKE ? OR p.sku LIKE ? OR m.reference_id LIKE ?)';array_push($ma,...array_fill(0,3,'%'.$f['q'].'%'));}return ["SELECT m.id,p.name,p.sku,m.movement_type,m.quantity_delta,m.unit_cost,m.reason,m.reference_type,m.reference_id,COALESCE(m.entry_date,DATE(m.created_at)) entry_date,m.created_at,m.previous_quantity,m.resulting_quantity FROM stock_movements m JOIN products p ON p.shop_id=m.shop_id AND p.id=m.product_id WHERE ".implode(' AND ',$where),$ma];
  }
  throw new DomainException('Choose a valid report dataset.');
 }
 public function sort(string $kind,array $f):string {
  $columns=match($kind){'exceptions'=>['id'],'products'=>['quantity','revenue','profit','margin','name'],'stock'=>['name','quantity','stock_value','sold_quantity'],'invoices','invoice_exceptions'=>['created_at','invoice_number','total'],'movements'=>['created_at','quantity_delta'], 'services'=>['created_at','revenue'], 'payments'=>['payment_date','amount'],default=>[]};
  $sort=in_array($f['sort'],$columns,true)?$f['sort']:$columns[0];$dir=strtoupper($f['direction']);return "$sort IS NULL ASC,$sort $dir,".(in_array($kind,['products','stock'],true)?'product_id':'id')." $dir";
 }
 public function page(string $kind,array $f,int $limit=25):array {[$sql,$args]=$this->dataset($kind,$f);$count=(int)$this->query("SELECT COUNT(*) FROM ($sql) rows_count",$args)->fetchColumn();$pages=max(1,(int)ceil($count/$limit));$page=min($f['page'],$pages);$rows=$this->query('SELECT * FROM ('.$sql.') report_data ORDER BY '.$this->sort($kind,$f).' LIMIT '.$limit.' OFFSET '.(($page-1)*$limit),$args)->fetchAll();return ['rows'=>$rows,'total'=>$count,'page'=>$page,'pages'=>$pages];}
 public function rows(string $kind,array $f):\Generator {[$sql,$args]=$this->dataset($kind,$f);$q=$this->query('SELECT * FROM ('.$sql.') report_data ORDER BY '.$this->sort($kind,$f),$args);while($row=$q->fetch())yield $row;}
 public function leaders(array $f,string $sort='quantity',bool $slow=false):array {[$sql,$args]=$this->dataset('products',array_replace($f,['q'=>'','category_id'=>null]));$sort=$sort==='revenue'?'revenue':'quantity';return $this->query("SELECT * FROM ($sql) ranked WHERE quantity>0 ORDER BY $sort ".($slow?'ASC':'DESC').',product_id ASC LIMIT 10',$args)->fetchAll();}
 public function movementSummary(array $f):array {[$sql,$args]=$this->dataset('movements',array_replace($f,['q'=>'']));return $this->query("SELECT movement_type,COUNT(*) entries,SUM(quantity_delta) delta,SUM(CASE WHEN quantity_delta>0 THEN quantity_delta ELSE 0 END) added,-SUM(CASE WHEN quantity_delta<0 THEN quantity_delta ELSE 0 END) removed FROM ($sql) movements GROUP BY movement_type ORDER BY movement_type",$args)->fetchAll();}
}
